import{_ as s,o as n,c as a}from"./chunks/framework.D1Ss-Xl7.js";const b=JSON.parse(`{"title":"Page 5 | Home","description":"","frontmatter":{"layout":"post-list"},"headers":[],"params":{"page":"5","title":"Page 5 | Home","prev":"/page/4/","next":"/page/6/","posts":[{"title":"安卓逆向的经验记录","url":"/posts/2023-01-14-android-reverse/","date":"2023-01-14 13:05","tags":["android"],"html":"<p>2023 年，博客也开通 10 年了。我都不敢看 10 年前自己写的东西。感觉全是黑历史，不过也记录了自己一点点的成长和心境的变化。今年也将继续写，记录自己技术上的各种折腾。</p>\\n<h2 id=\\"安卓逆向初体验\\" tabindex=\\"-1\\">安卓逆向初体验 <a class=\\"header-anchor\\" href=\\"#安卓逆向初体验\\" aria-label=\\"Permalink to &quot;安卓逆向初体验&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>首先自己知道了一个安卓电视盒子可以看全球的电视频道，我就想着干嘛要买人家的硬件，随便找个安卓手机不也可以使用么？于是找到了电视盒子上的软件，发现人家是有校验的。不是自家硬件初始化都无法通过。\\n于是我就好奇这个硬件校验是怎么做的，带着这个好奇心，开始了安卓逆向的征程。</p>\\n<h2 id=\\"java-代码脱壳\\" tabindex=\\"-1\\">Java 代码脱壳 <a class=\\"header-anchor\\" href=\\"#java-代码脱壳\\" aria-label=\\"Permalink to &quot;Java 代码脱壳&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>现在的安卓软件都会使用梆梆加固之类的软件防止别人进行逆向操作，所以第一步就是处理这个。先看到 JAVA 代码才能深入研究相关逻辑。经过同学指点，使用了一个 BlackDex 的工具。可以直接在安卓手机上进行脱壳操作。使用这个工具可以拿到 dex 文件。然后使用 jadx 输出 JAVA 代码。</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">jadx</span><span style=\\"color:#005CC5\\"> -d</span><span style=\\"color:#032F62\\"> dist_fold</span><span style=\\"color:#032F62\\"> ./cookie_xxx.dex</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><h3 id=\\"安卓手机抓包\\" tabindex=\\"-1\\">安卓手机抓包 <a class=\\"header-anchor\\" href=\\"#安卓手机抓包\\" aria-label=\\"Permalink to &quot;安卓手机抓包&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>拿到 JAVA 代码全部都读一遍也不现实，基于前端的逆向经验。我想先抓包看看请求内容。抓包软件使用的是 Charles 一款跨平台的抓包软件，不过是商业软件需要付费。\\n通过抓包分析到，请求全部是基于 HTTP 的，所以不需要再向安卓手机上安装抓包用的 CA 证书确实省事了不少。但是请求的数据和返回都是加密的。基于请求的字段并结合 JAVA 代码分析出加密使用的是 <code>aes-128-cbc</code> 算法。这个算法需要 key 和 iv 两个参数，那这两个参数是基于什么信息来生成的呢？通过请求带的特殊的 HTTP headers 进行猜测，应该是 <code>utctime</code> <code>mac</code> <code>model</code> 这三个参数。\\n为什么这么分析呢，因为服务器端需要进行解密，那必须要把需要的参数都告诉服务端才能把密文解密回明文。</p>\\n<h2 id=\\"加密算法逻辑分析\\" tabindex=\\"-1\\">加密算法逻辑分析 <a class=\\"header-anchor\\" href=\\"#加密算法逻辑分析\\" aria-label=\\"Permalink to &quot;加密算法逻辑分析&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>来到这里，最重要的是需要知道如何生成 key 和 iv 参数，因为 aes 是对称加密，我们知道这两个参数就能把密文再解析回明文。那就带着这个疑问来去读 JAVA 代码。</p>\\n<div class=\\"language-java line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">java</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">public</span><span style=\\"color:#D73A49\\"> class</span><span style=\\"color:#6F42C1\\"> EncryptRule</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    private</span><span style=\\"color:#D73A49\\"> static</span><span style=\\"color:#24292E\\"> String </span><span style=\\"color:#6F42C1\\">getEncrypKey</span><span style=\\"color:#24292E\\">(String </span><span style=\\"color:#E36209\\">str</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        String substring </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> MACUtils.</span><span style=\\"color:#6F42C1\\">getMac</span><span style=\\"color:#24292E\\">().</span><span style=\\"color:#6F42C1\\">substring</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">4</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#005CC5\\">10</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        return</span><span style=\\"color:#24292E\\"> MD5Util.</span><span style=\\"color:#6F42C1\\">getStringMD5_32</span><span style=\\"color:#24292E\\">(substring </span><span style=\\"color:#D73A49\\">+</span><span style=\\"color:#032F62\\"> \\"k3k7a3mM\\"</span><span style=\\"color:#D73A49\\"> +</span><span style=\\"color:#24292E\\"> str).</span><span style=\\"color:#6F42C1\\">substring</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">8</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#005CC5\\">24</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    }</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    private</span><span style=\\"color:#D73A49\\"> static</span><span style=\\"color:#24292E\\"> String </span><span style=\\"color:#6F42C1\\">getDecrypKey</span><span style=\\"color:#24292E\\">() {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        String substring </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> MACUtils.</span><span style=\\"color:#6F42C1\\">getMac</span><span style=\\"color:#24292E\\">().</span><span style=\\"color:#6F42C1\\">substring</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">4</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#005CC5\\">10</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        String str </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> Build.MODEL;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        return</span><span style=\\"color:#24292E\\"> MD5Util.</span><span style=\\"color:#6F42C1\\">getStringMD5_32</span><span style=\\"color:#24292E\\">(substring </span><span style=\\"color:#D73A49\\">+</span><span style=\\"color:#032F62\\"> \\"k3k7a3mM\\"</span><span style=\\"color:#D73A49\\"> +</span><span style=\\"color:#24292E\\"> str).</span><span style=\\"color:#6F42C1\\">substring</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">8</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#005CC5\\">24</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    }</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    public</span><span style=\\"color:#D73A49\\"> static</span><span style=\\"color:#24292E\\"> String </span><span style=\\"color:#6F42C1\\">getEncryptionParams</span><span style=\\"color:#24292E\\">(String </span><span style=\\"color:#E36209\\">str</span><span style=\\"color:#24292E\\">, String </span><span style=\\"color:#E36209\\">str2</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        String encrypKey </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#6F42C1\\"> getEncrypKey</span><span style=\\"color:#24292E\\">(str2);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        return</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> String</span><span style=\\"color:#24292E\\">(Base64.</span><span style=\\"color:#6F42C1\\">encodeBase64</span><span style=\\"color:#24292E\\">(AES.</span><span style=\\"color:#6F42C1\\">encrypt</span><span style=\\"color:#24292E\\">(str.</span><span style=\\"color:#6F42C1\\">getBytes</span><span style=\\"color:#24292E\\">(), encrypKey.</span><span style=\\"color:#6F42C1\\">getBytes</span><span style=\\"color:#24292E\\">(), encrypKey.</span><span style=\\"color:#6F42C1\\">getBytes</span><span style=\\"color:#24292E\\">())));</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    }</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    public</span><span style=\\"color:#D73A49\\"> static</span><span style=\\"color:#24292E\\"> String </span><span style=\\"color:#6F42C1\\">getSoEncryptionParams</span><span style=\\"color:#24292E\\">(String </span><span style=\\"color:#E36209\\">str</span><span style=\\"color:#24292E\\">, String </span><span style=\\"color:#E36209\\">str2</span><span style=\\"color:#24292E\\">, String </span><span style=\\"color:#E36209\\">str3</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        return</span><span style=\\"color:#24292E\\"> android.util.Base64.</span><span style=\\"color:#6F42C1\\">encodeToString</span><span style=\\"color:#24292E\\">(MainActivity.</span><span style=\\"color:#6F42C1\\">getJniApi</span><span style=\\"color:#24292E\\">().</span><span style=\\"color:#6F42C1\\">encodeAES</span><span style=\\"color:#24292E\\">(str.</span><span style=\\"color:#6F42C1\\">getBytes</span><span style=\\"color:#24292E\\">(), str3.</span><span style=\\"color:#6F42C1\\">getBytes</span><span style=\\"color:#24292E\\">(), str2.</span><span style=\\"color:#6F42C1\\">getBytes</span><span style=\\"color:#24292E\\">()), </span><span style=\\"color:#005CC5\\">2</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    }</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    public</span><span style=\\"color:#D73A49\\"> static</span><span style=\\"color:#24292E\\"> String </span><span style=\\"color:#6F42C1\\">getSoDecrypt</span><span style=\\"color:#24292E\\">(String </span><span style=\\"color:#E36209\\">str</span><span style=\\"color:#24292E\\">, String </span><span style=\\"color:#E36209\\">str2</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        try</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">            return</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> String</span><span style=\\"color:#24292E\\">(MainActivity.</span><span style=\\"color:#6F42C1\\">getJniApi</span><span style=\\"color:#24292E\\">().</span><span style=\\"color:#6F42C1\\">decodeAES</span><span style=\\"color:#24292E\\">(str.</span><span style=\\"color:#6F42C1\\">getBytes</span><span style=\\"color:#24292E\\">(), android.util.Base64.</span><span style=\\"color:#6F42C1\\">decode</span><span style=\\"color:#24292E\\">(str2.</span><span style=\\"color:#6F42C1\\">getBytes</span><span style=\\"color:#24292E\\">(), </span><span style=\\"color:#005CC5\\">2</span><span style=\\"color:#24292E\\">)));</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        } </span><span style=\\"color:#D73A49\\">catch</span><span style=\\"color:#24292E\\"> (Exception </span><span style=\\"color:#E36209\\">e</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">            e.</span><span style=\\"color:#6F42C1\\">printStackTrace</span><span style=\\"color:#24292E\\">();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">            return</span><span style=\\"color:#032F62\\"> \\"\\"</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    }</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    public</span><span style=\\"color:#D73A49\\"> static</span><span style=\\"color:#24292E\\"> String </span><span style=\\"color:#6F42C1\\">getDecrypt</span><span style=\\"color:#24292E\\">(String </span><span style=\\"color:#E36209\\">str</span><span style=\\"color:#24292E\\">) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">        return</span><span style=\\"color:#24292E\\"> AES.</span><span style=\\"color:#6F42C1\\">decrypt</span><span style=\\"color:#24292E\\">(str, </span><span style=\\"color:#6F42C1\\">getDecrypKey</span><span style=\\"color:#24292E\\">(), </span><span style=\\"color:#6F42C1\\">getDecrypKey</span><span style=\\"color:#24292E\\">(), </span><span style=\\"color:#032F62\\">\\"utf8\\"</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br><span class=\\"line-number\\">17</span><br><span class=\\"line-number\\">18</span><br><span class=\\"line-number\\">19</span><br><span class=\\"line-number\\">20</span><br><span class=\\"line-number\\">21</span><br><span class=\\"line-number\\">22</span><br><span class=\\"line-number\\">23</span><br><span class=\\"line-number\\">24</span><br><span class=\\"line-number\\">25</span><br><span class=\\"line-number\\">26</span><br><span class=\\"line-number\\">27</span><br><span class=\\"line-number\\">28</span><br><span class=\\"line-number\\">29</span><br><span class=\\"line-number\\">30</span><br><span class=\\"line-number\\">31</span><br><span class=\\"line-number\\">32</span><br><span class=\\"line-number\\">33</span><br><span class=\\"line-number\\">34</span><br></div></div><p>通过上面这段 JAVA 代码，我们知道加密的 key 是基于 MAC 地址信息进行生成的，传入的 str 参数其实是 <code>utctime</code> 。而解密 key 是基于 MAC 地址和 MODEL 信息，返回值的解密并没有用到 <code>utctime</code> 。返回信息的时候考虑到网络延迟 <code>utctime</code> 不是一个靠谱的参数。这里的 JAVA 逻辑是非核心请求的算法，我们想知道核心的播放列表信息的时候，发现它使用的是 <code>getSoEncryptionParams</code> 这个方法调用，而这个方法经过分析是调用 C++ 生成的 so 文件。逆向难度又上了一个台阶。顺便说下，经过 JAVA 代码分析 key 和 iv 其实是相同的参数。</p>\\n<h3 id=\\"so-文件分析\\" tabindex=\\"-1\\">so 文件分析 <a class=\\"header-anchor\\" href=\\"#so-文件分析\\" aria-label=\\"Permalink to &quot;so 文件分析&quot;\\">&ZeroWidthSpace;</a></h3>\\n<p>C++ 编译成 so 文件本质就是一个二进制文件。要想分析这个二进制文件需要很高的汇编功底和 C 语言知识，因为有些工具可以把二进制反编译成可读的 C 语言。经过同学点拨，使用了 <code>IDA Pro</code> 和 <code>Ghidra</code> 两个工具来对 so 文件进行逆向。so 文件的分析非常复杂，这里就只说结论了，so 里面分析出来的加解密算法和 JAVA 是一样的，但是中间拼接的字符串是不一样的。只要找到了核心的字符串就能完成请求的加解密。关于请求的解密，针对非英文字符，请使用 UTF-8 编码方式，由于我使用的工具默认采用 ASCII 编码，导致中文乱码，花了一段时间才找到原因。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>出于满足自己的好奇心，在各路同学的指点下，进行了安卓程序的逆向分析。非常有趣并且学到了很多知识，最后拿到了播放列表，但发现是基于一个私有的 <code>tvbus</code> 协议，没法移植到别的 APP 上使用，只能到此作罢。但是这次逆向分析的收获还是不少，在此记录一下。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://github.com/CodingGay/BlackDex\\" target=\\"_blank\\" rel=\\"noreferrer\\">BlackDex</a></p>\\n<p><a href=\\"https://github.com/skylot/\\" target=\\"_blank\\" rel=\\"noreferrer\\">jadx</a></p>\\n<p><a href=\\"https://www.charlesproxy.com/\\" target=\\"_blank\\" rel=\\"noreferrer\\">Charles</a></p>\\n<p><a href=\\"https://gchq.github.io/CyberChef/\\" target=\\"_blank\\" rel=\\"noreferrer\\">CyberChef</a></p>\\n<p><a href=\\"https://github.com/NationalSecurityAgency/ghidra\\" target=\\"_blank\\" rel=\\"noreferrer\\">Ghidra</a></p>\\n<p><a href=\\"https://hex-rays.com/ida-pro/\\" target=\\"_blank\\" rel=\\"noreferrer\\">IDA Pro</a></p>\\n<p><a href=\\"https://gist.github.com/acgotaku/091a7a5d181b3211392b0fbdaf37d347\\" target=\\"_blank\\" rel=\\"noreferrer\\">EncryptRule</a></p>\\n"},{"title":"网页调用摄像头读取QR code","url":"/posts/2022-12-17-web-qr-reader/","date":"2022-12-17 17:29","tags":["qrcode"],"html":"<p>2022 年也要结束了，博客不能停更。最近项目中有读取 QR 码的需求，于是便调研了下如何实现这个功能，顺便写篇博客记录下。</p>\\n<h2 id=\\"现成-react-框架\\" tabindex=\\"-1\\">现成 React 框架 <a class=\\"header-anchor\\" href=\\"#现成-react-框架\\" aria-label=\\"Permalink to &quot;现成 React 框架&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>首先调研了别人封装好的现成框架，<a href=\\"https://github.com/react-qr-reader/react-qr-reader\\" target=\\"_blank\\" rel=\\"noreferrer\\">React QR Reader</a>。这个框架看起来还挺流行的，可是最新版本的发布已经是 2019 年了。\\n而且有一个致命的 BUG 就是在开启摄像头之后无法关闭。必须重新刷新页面才行，这是不能接受的。</p>\\n<h2 id=\\"低层封装框架\\" tabindex=\\"-1\\">低层封装框架 <a class=\\"header-anchor\\" href=\\"#低层封装框架\\" aria-label=\\"Permalink to &quot;低层封装框架&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>发现大家基本都是调用<a href=\\"https://github.com/zxing-js/browser\\" target=\\"_blank\\" rel=\\"noreferrer\\">@zxing/browser</a>来完成核心功能的。于是我也使用这个框架封装一个不就好了。\\n首先安装相关依赖：</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">pnpm</span><span style=\\"color:#032F62\\"> add</span><span style=\\"color:#032F62\\"> @zxing/browser</span><span style=\\"color:#032F62\\"> @zxing/library</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>具体的封装代码如下：</p>\\n<div class=\\"language-tsx line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">tsx</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#D73A49\\">const</span><span style=\\"color:#6F42C1\\"> QrReader</span><span style=\\"color:#D73A49\\">:</span><span style=\\"color:#6F42C1\\"> React</span><span style=\\"color:#24292E\\">.</span><span style=\\"color:#6F42C1\\">FC</span><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">IQrReaderProps</span><span style=\\"color:#24292E\\">> </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> ({</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  videoId </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\"> 'video'</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  scanDelay </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> 500</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  constraints </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    facingMode: </span><span style=\\"color:#032F62\\">'environment'</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  },</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  className </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#032F62\\"> ''</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  onResult</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}) </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> stopRef</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> useRef</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">false</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  const</span><span style=\\"color:#005CC5\\"> videoRef</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#6F42C1\\"> useRef</span><span style=\\"color:#24292E\\">&#x3C;</span><span style=\\"color:#6F42C1\\">HTMLVideoElement</span><span style=\\"color:#D73A49\\"> |</span><span style=\\"color:#005CC5\\"> null</span><span style=\\"color:#24292E\\">>(</span><span style=\\"color:#005CC5\\">null</span><span style=\\"color:#24292E\\">);</span></span>\\n<span class=\\"line\\"></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">  useEffect</span><span style=\\"color:#24292E\\">(() </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    if</span><span style=\\"color:#24292E\\"> (videoRef.current) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">      const</span><span style=\\"color:#005CC5\\"> codeReader</span><span style=\\"color:#D73A49\\"> =</span><span style=\\"color:#D73A49\\"> new</span><span style=\\"color:#6F42C1\\"> BrowserQRCodeReader</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">undefined</span><span style=\\"color:#24292E\\">, {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        delayBetweenScanAttempts: scanDelay</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      });</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      stopRef.current </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> false</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      codeReader</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        .</span><span style=\\"color:#6F42C1\\">decodeFromConstraints</span><span style=\\"color:#24292E\\">(</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">            video: constraints</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          },</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          videoRef.current,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          (</span><span style=\\"color:#E36209\\">result</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#E36209\\">error</span><span style=\\"color:#24292E\\">, </span><span style=\\"color:#E36209\\">controls</span><span style=\\"color:#24292E\\">) </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">            onResult </span><span style=\\"color:#D73A49\\">&#x26;&#x26;</span><span style=\\"color:#6F42C1\\"> onResult</span><span style=\\"color:#24292E\\">(result, error, controls);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">            if</span><span style=\\"color:#24292E\\"> (stopRef.current) {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">              controls.</span><span style=\\"color:#6F42C1\\">stop</span><span style=\\"color:#24292E\\">();</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">            }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        )</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        .</span><span style=\\"color:#6F42C1\\">catch</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#E36209\\">error</span><span style=\\"color:#D73A49\\"> =></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          onResult </span><span style=\\"color:#D73A49\\">&#x26;&#x26;</span><span style=\\"color:#6F42C1\\"> onResult</span><span style=\\"color:#24292E\\">(</span><span style=\\"color:#005CC5\\">undefined</span><span style=\\"color:#24292E\\">, error);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        });</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    }</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">    return</span><span style=\\"color:#24292E\\"> () </span><span style=\\"color:#D73A49\\">=></span><span style=\\"color:#24292E\\"> {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      stopRef.current </span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#005CC5\\"> true</span><span style=\\"color:#24292E\\">;</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    };</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  }, [videoId, scanDelay, constraints, onResult]);</span></span>\\n<span class=\\"line\\"><span style=\\"color:#D73A49\\">  return</span><span style=\\"color:#24292E\\"> (</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    &#x3C;</span><span style=\\"color:#22863A\\">section</span><span style=\\"color:#6F42C1\\"> className</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">{</span><span style=\\"color:#6F42C1\\">cls</span><span style=\\"color:#24292E\\">(styles.reader, className)}></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      &#x3C;</span><span style=\\"color:#22863A\\">div</span><span style=\\"color:#6F42C1\\"> className</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">{styles.container}></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        &#x3C;</span><span style=\\"color:#005CC5\\">ViewFinder</span><span style=\\"color:#24292E\\"> /></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        &#x3C;</span><span style=\\"color:#22863A\\">video</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">          muted</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">          ref</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">{videoRef}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">          className</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">{styles.video}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#6F42C1\\">          style</span><span style=\\"color:#D73A49\\">=</span><span style=\\"color:#24292E\\">{{</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">            transform:</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">              constraints?.facingMode </span><span style=\\"color:#D73A49\\">===</span><span style=\\"color:#032F62\\"> 'user'</span><span style=\\"color:#D73A49\\"> ?</span><span style=\\"color:#032F62\\"> 'scaleX(-1)'</span><span style=\\"color:#D73A49\\"> :</span><span style=\\"color:#032F62\\"> 'none'</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">          }}</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">        /></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">      &#x3C;/</span><span style=\\"color:#22863A\\">div</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    &#x3C;/</span><span style=\\"color:#22863A\\">section</span><span style=\\"color:#24292E\\">></span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  );</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">};</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br><span class=\\"line-number\\">17</span><br><span class=\\"line-number\\">18</span><br><span class=\\"line-number\\">19</span><br><span class=\\"line-number\\">20</span><br><span class=\\"line-number\\">21</span><br><span class=\\"line-number\\">22</span><br><span class=\\"line-number\\">23</span><br><span class=\\"line-number\\">24</span><br><span class=\\"line-number\\">25</span><br><span class=\\"line-number\\">26</span><br><span class=\\"line-number\\">27</span><br><span class=\\"line-number\\">28</span><br><span class=\\"line-number\\">29</span><br><span class=\\"line-number\\">30</span><br><span class=\\"line-number\\">31</span><br><span class=\\"line-number\\">32</span><br><span class=\\"line-number\\">33</span><br><span class=\\"line-number\\">34</span><br><span class=\\"line-number\\">35</span><br><span class=\\"line-number\\">36</span><br><span class=\\"line-number\\">37</span><br><span class=\\"line-number\\">38</span><br><span class=\\"line-number\\">39</span><br><span class=\\"line-number\\">40</span><br><span class=\\"line-number\\">41</span><br><span class=\\"line-number\\">42</span><br><span class=\\"line-number\\">43</span><br><span class=\\"line-number\\">44</span><br><span class=\\"line-number\\">45</span><br><span class=\\"line-number\\">46</span><br><span class=\\"line-number\\">47</span><br><span class=\\"line-number\\">48</span><br><span class=\\"line-number\\">49</span><br><span class=\\"line-number\\">50</span><br><span class=\\"line-number\\">51</span><br><span class=\\"line-number\\">52</span><br><span class=\\"line-number\\">53</span><br><span class=\\"line-number\\">54</span><br><span class=\\"line-number\\">55</span><br><span class=\\"line-number\\">56</span><br></div></div><p>这里使用了 <code>stopRef</code> 来标记组件的销毁并停止调用摄像头。本身封装也不复杂，没必要使用别人封装的轮子。完整的代码在<a href=\\"https://github.com/acgotaku/simple-qr-reader\\" target=\\"_blank\\" rel=\\"noreferrer\\">simple-qr-reader</a></p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>前端生态非常完善，使用现成的库就可以非常方便的实现调用摄像头读取二维码功能。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://zenn.dev/terrierscript/articles/2020-12-22-zxing-browser-react-qr-code-reader\\" target=\\"_blank\\" rel=\\"noreferrer\\">@zxing/browser と React の組み合わせで QR Code Reader 作る</a></p>\\n"},{"title":"如何使用TypeScript进行后端开发","url":"/posts/2022-10-29-typescript-backend/","date":"2022-10-29 11:47","tags":["TypeScript"],"html":"<p>我们经常使用 TypeScript 进行开发，webpack 会自动帮我们编译成浏览器可以执行的 JS 文件。相关的开发工具也很完善，但是进行后端开发的资料就比较少了，我们来讲解下如何使用 TypeScript 进行后端开发。</p>\\n<h2 id=\\"开发环境自动重新加载\\" tabindex=\\"-1\\">开发环境自动重新加载 <a class=\\"header-anchor\\" href=\\"#开发环境自动重新加载\\" aria-label=\\"Permalink to &quot;开发环境自动重新加载&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>前端有 <a href=\\"https://webpack.js.org/concepts/hot-module-replacement/\\" target=\\"_blank\\" rel=\\"noreferrer\\">HMR</a> 技术可以实在自动热加载。后端实现这个功能其实也很简单。 首先需要按照 <code>nodemon</code> 和 <code>ts-node</code>。\\n我们使用 pnpm 进行包管理。</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">pnpm</span><span style=\\"color:#032F62\\"> add</span><span style=\\"color:#032F62\\"> nodemon</span><span style=\\"color:#032F62\\"> ts-node</span><span style=\\"color:#005CC5\\"> -D</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>然后在 <code>package.json</code> 添加命令。</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">nodemon</span><span style=\\"color:#032F62\\"> src/index.ts</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p><code>nodemon</code> 可以完成对文件的监控并且自动 reload，<code>ts-node</code> 完成对 TypeScript 的支持。并且不需要配置，<code>nodemon</code> 会自动调用 <code>ts-node</code>。</p>\\n<h2 id=\\"支持绝对路径引用\\" tabindex=\\"-1\\">支持绝对路径引用 <a class=\\"header-anchor\\" href=\\"#支持绝对路径引用\\" aria-label=\\"Permalink to &quot;支持绝对路径引用&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>前端开发中也经常使用绝对路径，所以希望后端也能使用绝对路径。TypeScript 默认不支持绝对路径的使用，我们需要引用第三方来完成这个操作。</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">pnpm</span><span style=\\"color:#032F62\\"> add</span><span style=\\"color:#032F62\\"> ttypescript</span><span style=\\"color:#032F62\\"> typescript-transform-paths</span><span style=\\"color:#005CC5\\"> -D</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>ttypescript 支持在 build 过程中添加插件来完成很多功能，绝对路径转换成相对路径就是其中一个功能， typescript-transform-paths 这个插件就是用来完成绝对路径映射的。我们需要在 <code>tsconfig.json</code> 中进行相关的配置。</p>\\n<div class=\\"language-json line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">json</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#24292E\\">{</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">  \\"ts-node\\"</span><span style=\\"color:#24292E\\">: {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"transpileOnly\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#005CC5\\">true</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"require\\"</span><span style=\\"color:#24292E\\">: [</span><span style=\\"color:#032F62\\">\\"typescript-transform-paths/register\\"</span><span style=\\"color:#24292E\\">]</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  },</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">  \\"compilerOptions\\"</span><span style=\\"color:#24292E\\">: {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"target\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#032F62\\">\\"ESNext\\"</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"module\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#032F62\\">\\"commonjs\\"</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"moduleResolution\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#032F62\\">\\"Node\\"</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"outDir\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#032F62\\">\\"dist\\"</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"resolveJsonModule\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#005CC5\\">true</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"skipLibCheck\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#005CC5\\">true</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"experimentalDecorators\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#005CC5\\">true</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"emitDecoratorMetadata\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#005CC5\\">true</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"esModuleInterop\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#005CC5\\">true</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"allowSyntheticDefaultImports\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#005CC5\\">true</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"baseUrl\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#032F62\\">\\".\\"</span><span style=\\"color:#24292E\\">,</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"paths\\"</span><span style=\\"color:#24292E\\">: {</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">      \\"@/*\\"</span><span style=\\"color:#24292E\\">: [</span><span style=\\"color:#032F62\\">\\"src/*\\"</span><span style=\\"color:#24292E\\">]</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">    },</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">    \\"plugins\\"</span><span style=\\"color:#24292E\\">: [{ </span><span style=\\"color:#005CC5\\">\\"transform\\"</span><span style=\\"color:#24292E\\">: </span><span style=\\"color:#032F62\\">\\"typescript-transform-paths\\"</span><span style=\\"color:#24292E\\"> }]</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">  },</span></span>\\n<span class=\\"line\\"><span style=\\"color:#005CC5\\">  \\"include\\"</span><span style=\\"color:#24292E\\">: [</span><span style=\\"color:#032F62\\">\\"src\\"</span><span style=\\"color:#24292E\\">]</span></span>\\n<span class=\\"line\\"><span style=\\"color:#24292E\\">}</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br><span class=\\"line-number\\">2</span><br><span class=\\"line-number\\">3</span><br><span class=\\"line-number\\">4</span><br><span class=\\"line-number\\">5</span><br><span class=\\"line-number\\">6</span><br><span class=\\"line-number\\">7</span><br><span class=\\"line-number\\">8</span><br><span class=\\"line-number\\">9</span><br><span class=\\"line-number\\">10</span><br><span class=\\"line-number\\">11</span><br><span class=\\"line-number\\">12</span><br><span class=\\"line-number\\">13</span><br><span class=\\"line-number\\">14</span><br><span class=\\"line-number\\">15</span><br><span class=\\"line-number\\">16</span><br><span class=\\"line-number\\">17</span><br><span class=\\"line-number\\">18</span><br><span class=\\"line-number\\">19</span><br><span class=\\"line-number\\">20</span><br><span class=\\"line-number\\">21</span><br><span class=\\"line-number\\">22</span><br><span class=\\"line-number\\">23</span><br><span class=\\"line-number\\">24</span><br></div></div><p>首先在 <code>paths</code> 字段下，映射文件夹路径，这样就可以使用 <code>@/posts/index.ts</code> 这种格式来引用模块。当然路径映射在开发环境下需要 <code>ts-node</code> 的支持，我们在 <code>ts-node</code> 的 <code>require</code> 字段上引用我们安装的插件。最后是编译成 JS 文件的过程中添加绝对路径的支持。</p>\\n<div class=\\"language-bash line-numbers-mode\\"><button title=\\"Copy Code\\" class=\\"copy\\"></button><span class=\\"lang\\">bash</span><pre class=\\"shiki github-light vp-code\\" tabindex=\\"0\\" v-pre=\\"\\"><code><span class=\\"line\\"><span style=\\"color:#6F42C1\\">ttsc</span><span style=\\"color:#005CC5\\"> -p</span><span style=\\"color:#032F62\\"> tsconfig.json</span></span></code></pre>\\n<div class=\\"line-numbers-wrapper\\" aria-hidden=\\"true\\"><span class=\\"line-number\\">1</span><br></div></div><p>使用增强版 <code>ttsc</code> 来完成路径的转换，可以看到生成的 JS 文件中已经是正常的相对路径引用了，前端的时候大多数都是 webpack 完成打包的，后端的话可以直接使用 <code>ttsc</code> 来完成编译过程。</p>\\n<h2 id=\\"总结\\" tabindex=\\"-1\\">总结 <a class=\\"header-anchor\\" href=\\"#总结\\" aria-label=\\"Permalink to &quot;总结&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p>TypeScript 在类型定义上的支持可以让我们很方便开发大型项目，后端支持了 reload 和绝对路径之后开发效率也可以大大提高。</p>\\n<h2 id=\\"参考\\" tabindex=\\"-1\\">参考 <a class=\\"header-anchor\\" href=\\"#参考\\" aria-label=\\"Permalink to &quot;参考&quot;\\">&ZeroWidthSpace;</a></h2>\\n<p><a href=\\"https://chaika.hatenablog.com/entry/2021/12/20/083000\\" target=\\"_blank\\" rel=\\"noreferrer\\">ts-node で path alias が効かないにハマる</a></p>\\n<p><a href=\\"https://github.com/acgotaku/mapdoge-bot\\" target=\\"_blank\\" rel=\\"noreferrer\\">mapdoge-bot</a></p>\\n"}]},"relativePath":"page/5/index.md","filePath":"page/[page].md"}`),p={name:"page/5/index.md"};function l(e,o,r,c,t,i){return n(),a("div")}const d=s(p,[["render",l]]);export{b as __pageData,d as default};
